// Prepare binary data from base64 attachment for the Gemini Vision node
const attachment = $input.first().json.body.attachment;

if (attachment && attachment.base64) {
  const binaryData = Buffer.from(attachment.base64, 'base64');

  const items = [{
    json: $input.first().json,
    binary: {
      data: {
        data: attachment.base64,
        mimeType: attachment.mimeType,
        fileName: attachment.name,
      }
    }
  }];

  return items;
}

return $input.all();
